<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';require_permission('projects.view');$pageTitle='Portafolio de proyectos';$pdo=db();
$status=(string)($_GET['status']??'');$health=(string)($_GET['health']??'');$owner=(int)($_GET['owner']??0);$q=trim((string)($_GET['q']??''));$where=['1=1'];$params=[];
if(in_array($status,['planning','active','on_hold','completed','cancelled'],true)){$where[]='p.status=?';$params[]=$status;}if(in_array($health,['on_track','at_risk','off_track'],true)){$where[]='p.health=?';$params[]=$health;}if($owner){$where[]='p.owner_user_id=?';$params[]=$owner;}if($q!==''){$where[]='(p.name LIKE ? OR p.code LIKE ? OR c.company_name LIKE ?)';$term='%'.$q.'%';array_push($params,$term,$term,$term);}
$s=$pdo->prepare("SELECT p.*,c.company_name,u.name owner_name,(SELECT COUNT(*) FROM project_tasks t WHERE t.project_id=p.id) task_count,(SELECT COUNT(*) FROM project_tasks t WHERE t.project_id=p.id AND t.status='done') done_count,(SELECT COALESCE(SUM(hours),0) FROM project_time_entries te WHERE te.project_id=p.id) logged_hours FROM projects p LEFT JOIN clients c ON c.id=p.client_id LEFT JOIN users u ON u.id=p.owner_user_id WHERE ".implode(' AND ',$where)." ORDER BY FIELD(p.status,'active','planning','on_hold','completed','cancelled'),p.due_date IS NULL,p.due_date,p.name");$s->execute($params);$rows=$s->fetchAll();$users=$pdo->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();require __DIR__.'/includes/header.php';?>
<div class="project-hero compact"><div><span class="eyebrow">PORTAFOLIO</span><h2>Todos los proyectos</h2><p>Vista ejecutiva para controlar responsables, fechas, salud, carga y avance.</p></div><?php if(has_permission('projects.manage')):?><a class="btn btn-primary" href="project_form.php">+ NUEVO PROYECTO</a><?php endif;?></div>
<section class="panel"><div class="panel-body"><form class="filters-wide" method="get"><label>Buscar<input name="q" value="<?=e($q)?>" placeholder="Proyecto, código o cliente"></label><label>Estado<select name="status"><option value="">Todos</option><?php foreach(['planning','active','on_hold','completed','cancelled'] as$x):?><option value="<?=$x?>" <?=$status===$x?'selected':''?>><?=e(pm_status_label($x))?></option><?php endforeach;?></select></label><label>Salud<select name="health"><option value="">Todas</option><?php foreach(['on_track','at_risk','off_track'] as$x):?><option value="<?=$x?>" <?=$health===$x?'selected':''?>><?=e(pm_health_label($x))?></option><?php endforeach;?></select></label><label>Responsable<select name="owner"><option value="0">Todos</option><?php foreach($users as$u):?><option value="<?=$u['id']?>" <?=$owner===(int)$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><button class="btn btn-secondary">FILTRAR</button></form></div></section>
<div class="pm-project-grid"><?php if(!$rows):?><section class="panel"><div class="empty">No hay proyectos con estos filtros.</div></section><?php endif;?><?php foreach($rows as$p):?><article class="pm-project-card" style="--project-color:<?=e($p['color'])?>"><div class="pm-project-card-head"><span class="pm-project-code"><?=e($p['code']?:'PROYECTO')?></span><?=pm_badge($p['health'],'health')?></div><h3><a href="project_view.php?id=<?=$p['id']?>"><?=e($p['name'])?></a></h3><p><?=e($p['company_name']?:'Proyecto interno')?> · <?=e($p['owner_name']?:'Sin responsable')?></p><div class="pm-progress big"><span style="width:<?=(int)$p['progress']?>%"></span></div><div class="pm-project-stats"><span><small>AVANCE</small><strong><?=(int)$p['progress']?>%</strong></span><span><small>TAREAS</small><strong><?=(int)$p['done_count']?>/<?=(int)$p['task_count']?></strong></span><span><small>HORAS</small><strong><?=e(number_format((float)$p['logged_hours'],1,',','.'))?></strong></span></div><div class="pm-project-card-foot"><span><?=pm_badge($p['status'])?></span><span><?=crm_icon('calendar')?> <?=e(pm_date($p['due_date']))?></span></div></article><?php endforeach;?></div>
<?php require __DIR__.'/includes/footer.php';?>
